function getWebConfig() {
  const fetchNode = $('Fetch User Config').first()?.json;
  if (fetchNode?.config) return fetchNode.config;
  const legacy = $('Get Search Config').first()?.json;
  return legacy?.config ?? legacy ?? {};
}

const cfg = getWebConfig();
const queries = Array.isArray(cfg.search_queries) ? cfg.search_queries : [];
const baseUrl = String(cfg.searxng_base_url || 'http://152.53.157.68:8080/search').replace(/\/$/, '');

if (queries.length === 0) {
  throw new Error('No search queries configured. Add them in jobs.mubu.dev/settings → Job Search.');
}

return queries.map(query => ({
  json: {
    query,
    search_url: baseUrl + '?q=' + encodeURIComponent(query) + '&format=json&language=de-DE'
  }
}));

const items = $input.all();
const merged = [];
const seen = new Set();

for (const item of items) {
  const results = item.json.results ?? [];
  for (const result of results) {
    const url = String(result.url ?? '').trim();
    if (!url || seen.has(url)) continue;
    seen.add(url);
    merged.push(result);
  }
}

return [{
  json: {
    results: merged,
    search_query_count: items.length,
    raw_result_count: merged.length
  }
}];

function getWebConfig() {
  const fetchNode = $('Fetch User Config').first()?.json;
  if (fetchNode?.config) return fetchNode.config;
  if (fetchNode?.user_id) return fetchNode;
  const legacy = $('Get Search Config').first()?.json;
  return legacy?.config ?? legacy ?? {};
}

const cfg = getWebConfig();
const results = $input.first().json.results ?? [];

const slimResults = results.map(r => ({
  title: r.title,
  content: r.content,
  url: r.url,
  score: r.score
}));

const roleKeywords = String(cfg.role_keywords || 'Werkstudent / Working Student');
const techFocus = String(cfg.tech_focus || 'software development, Python, React, AI');
const maxJobs = Math.min(Math.max(Number(cfg.max_jobs_per_run) || 20, 1), 50);
const locations = Array.isArray(cfg.preferred_locations) ? cfg.preferred_locations : ['Köln', 'Cologne'];
const locationHint = locations.slice(0, 3).join(', ');
const allowRemote = cfg.allow_remote_outside_locations !== false;

const locationRules =
  `Jobs in ${locationHint} may be onsite, hybrid or remote. ` +
  (allowRemote
    ? 'Jobs outside those locations should only be included when the search result clearly indicates remote work from Germany. '
    : 'Only include jobs in the preferred locations. ');

const payload = {
  model: 'deepseek-v4-flash',
  reasoning: { effort: 'none' },
  max_output_tokens: 6000,
  instructions:
    'You are a job result extraction and selection agent. You receive search results from SearXNG. ' +
    `Extract actual ${roleKeywords} job postings relevant to computer science. ` +
    `Prefer ${techFocus}. ` +
    'Exclude internships, full-time jobs and clearly irrelevant results. ' +
    'Every returned job MUST have a URL that points to the individual job posting itself. ' +
    'NEVER return URLs that point only to search result pages, job category pages, career overview pages, ' +
    'company homepages, generic job-board pages, or pages containing multiple different job postings. ' +
    'If no specific individual job posting URL can be identified, DO NOT return that job. ' +
    'Employer diversity is very important. Return a maximum of 2 jobs from the same employer or company group. ' +
    'Detect duplicate or near-duplicate job postings and return each position only once. ' +
    `Aim to return up to ${maxJobs} useful jobs if enough suitable jobs exist. ` +
    'Do not invent information. If location cannot be determined, use unknown. ' +
    'For work_mode use unknown when necessary. A job URL must never be unknown; exclude the job instead. ' +
    'Return only the structured JSON output.',
  input:
    `Analyze the following SearXNG search results and extract relevant ${roleKeywords} jobs. ` +
    locationRules +
    'Create a diverse selection across employers. For every actual job posting return title, company, location, work_mode and URL.\n\n' +
    'SEARXNG RESULTS:\n\n' +
    JSON.stringify(slimResults),
  text: {
    format: {
      type: 'json_schema',
      name: 'job_search_results',
      strict: true,
      schema: {
        type: 'object',
        properties: {
          jobs: {
            type: 'array',
            maxItems: maxJobs,
            items: {
              type: 'object',
              properties: {
                title: { type: 'string' },
                company: { type: 'string' },
                location: { type: 'string' },
                work_mode: {
                  type: 'string',
                  enum: ['onsite', 'hybrid', 'remote', 'unknown']
                },
                url: { type: 'string' }
              },
              required: ['title', 'company', 'location', 'work_mode', 'url'],
              additionalProperties: false
            }
          }
        },
        required: ['jobs'],
        additionalProperties: false
      }
    }
  }
};

return [{ json: { deepseek_body: payload } }];

const response = $input.first().json;
const candidates = [];

if (Array.isArray(response.output)) {
  for (const item of response.output) {
    if (!Array.isArray(item.content)) continue;
    for (const content of item.content) {
      if (typeof content.text === 'string') candidates.push(content.text);
      if (typeof content.output_text === 'string') candidates.push(content.output_text);
    }
  }
}

if (Array.isArray(response.choices)) {
  for (const choice of response.choices) {
    const content = choice?.message?.content;
    if (typeof content === 'string') candidates.push(content);
  }
}

if (typeof response.content === 'string') candidates.push(response.content);
if (typeof response.text === 'string') candidates.push(response.text);

if (candidates.length === 0) {
  return [];
}

let parsed = null;
let lastError = null;

for (const candidate of candidates) {
  try {
    let text = candidate.trim()
      .replace(/^\`\`\`(?:json)?\s*/i, '')
      .replace(/\s*\`\`\`$/i, '')
      .trim();

    const firstBrace = text.indexOf('{');
    const lastBrace = text.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1) {
      text = text.slice(firstBrace, lastBrace + 1);
    }

    const result = JSON.parse(text);
    if (Array.isArray(result.jobs)) {
      parsed = result;
      break;
    }
  } catch (error) {
    lastError = error;
  }
}

if (!parsed || !Array.isArray(parsed.jobs) || parsed.jobs.length === 0) {
  return [];
}

return parsed.jobs.map(job => ({
  json: {
    title: job.title ?? '',
    company: job.company ?? '',
    location: job.location ?? 'unknown',
    work_mode: job.work_mode ?? 'unknown',
    url: job.url ?? ''
  }
}));

function getWebConfig() {
  const fetchNode = $('Fetch User Config').first()?.json;
  if (fetchNode?.config) return fetchNode.config;
  const legacy = $('Get Search Config').first()?.json;
  return legacy?.config ?? legacy ?? {};
}

const cfg = getWebConfig();
const items = $input.all();

function normText(value) {
  return String(value ?? '')
    .toLowerCase()
    .replace(/ä/g, 'a')
    .replace(/ö/g, 'o')
    .replace(/ü/g, 'u')
    .replace(/ß/g, 'ss')
    .trim();
}

const preferred = (Array.isArray(cfg.preferred_locations) ? cfg.preferred_locations : [])
  .map(normText)
  .filter(Boolean);

const allowRemote = cfg.allow_remote_outside_locations !== false;

return items.filter(item => {
  const job = item.json;
  const location = normText(job.location);
  const workMode = normText(job.work_mode);

  const isPreferred = preferred.some(place => location.includes(place));
  if (isPreferred) return true;

  const isRemote =
    workMode === 'remote' ||
    workMode === 'fully remote' ||
    workMode.includes('fully remote');

  if (allowRemote && isRemote) return true;

  return false;
});

function normText(value) {
  return String(value ?? '')
    .toLowerCase()
    .replace(/ä/g, 'a')
    .replace(/ö/g, 'o')
    .replace(/ü/g, 'u')
    .replace(/ß/g, 'ss')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function normCompany(value) {
  return normText(value)
    .replace(/\b(gmbh|ag|kg|co|inc|ltd|group|gruppe|se|mbh)\b/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normUrl(url) {
  try {
    const parsed = new URL(String(url).trim());
    parsed.hash = '';
    parsed.search = '';
    const path = parsed.pathname.replace(/\/+$/, '');
    return (parsed.hostname.replace(/^www\./, '') + path).toLowerCase();
  } catch (error) {
    return normText(url);
  }
}

function fingerprint(job) {
  const urlKey = normUrl(job.url);
  if (urlKey.length > 8) {
    return 'url:' + urlKey;
  }
  const company = normCompany(job.company);
  const title = normText(job.title);
  return 'tc:' + company + '|' + title;
}

const seen = new Set();

return $input.all().filter(item => {
  const key = fingerprint(item.json);
  if (!key || key === 'tc:|') {
    return Boolean(String(item.json.title ?? '').trim() && String(item.json.company ?? '').trim());
  }
  if (seen.has(key)) {
    return false;
  }
  seen.add(key);
  return true;
});

return $input.all()
  .filter(item => {
    const j = item.json;
    const title = String(j.job_title ?? j.title ?? '').trim();
    const company = String(j.company ?? '').trim();
    return title.length > 0 && company.length > 0;
  })
  .map(item => {
  const j = item.json;
  const m = j.match ?? {};
  const arr = v => Array.isArray(v) ? v : [];
  const statusText = [j.job_title, j.job_description].filter(Boolean).join(' ').toLowerCase();
  const expiredPhrases = ['this vacancy has now expired','vacancy has expired','position has been filled','position is no longer available','job is no longer available','stelle bereits besetzt','stelle ist bereits besetzt','stelle wurde bereits besetzt','stelle ist besetzt','stelle nicht mehr verfügbar','position nicht mehr verfügbar'];
  const isExpired = expiredPhrases.some(phrase => statusText.includes(phrase));
  const score = m.score != null && !isNaN(Number(m.score)) ? Number(m.score) : (j.match_score != null && !isNaN(Number(j.match_score)) ? Number(j.match_score) : null);
  const uid = $('Fetch User Config').first()?.json?.user_id ?? null;
  return { json: { user_id: uid, job_title: j.job_title ?? j.title ?? '', company: j.company ?? '', location: j.location ?? null, url: j.url || null, source_url: j.source_url || j.url || null, remote_option: j.remote_option ?? j.work_mode ?? null, home_office_available: typeof j.home_office_available === 'boolean' ? j.home_office_available : null, employment_type: j.employment_type ?? null, weekly_hours: j.weekly_hours != null && !isNaN(Number(j.weekly_hours)) ? Number(j.weekly_hours) : null, start_date: j.start_date ?? null, date_posted: /^\d{4}-\d{2}-\d{2}$/.test(j.date_posted ?? '') ? j.date_posted : null, job_description: j.job_description ?? null, required_technologies: arr(j.required_technologies), preferred_technologies: arr(j.preferred_technologies), required_requirements: arr(j.required_requirements), preferred_requirements: arr(j.preferred_requirements), tasks: arr(j.tasks), degree_fields: arr(j.degree_fields), required_languages: arr(j.required_languages), preferred_languages: arr(j.preferred_languages), minimum_semester: j.minimum_semester != null && !isNaN(Number(j.minimum_semester)) ? Number(j.minimum_semester) : null, previous_work_experience_required: j.previous_work_experience_required === true, student_required: typeof j.student_required === 'boolean' ? j.student_required : null, required_experience: j.required_experience ?? null, match_score: score, match_recommendation: m.recommendation ?? j.match_recommendation ?? null, matched_required_technologies: arr(m.matched_required_technologies), matched_preferred_technologies: arr(m.matched_preferred_technologies), missing_required_technologies: arr(m.missing_required_technologies), matched_technical_areas: arr(m.matched_technical_areas), match_positives: arr(m.positives), match_warnings: arr(m.warnings), analysis_status: j.analysis_status ?? null, fetch_status_code: j.fetch_status_code ?? null, extraction_error: j.extraction_error ?? null, status: isExpired ? 'expired' : 'new' } };
});

