function safeItems(nodeName) {
  try {
    return $items(nodeName);
  } catch (error) {
    return [];
  }
}

const processed = $input.all();
const newJobs = processed.filter(item => item.json._was_new === true).length;
const existingJobs = processed.filter(item => item.json._was_new === false).length;

const searxMerged = safeItems('Merge SearXNG Results')[0]?.json ?? safeItems('SearXNG Search')[0]?.json ?? {};
const searchRun = safeItems('Create Search Run')[0]?.json ?? {};

const resultsFound = Array.isArray(searxMerged.results) ? searxMerged.results.length : 0;
const searchQueryCount = searxMerged.search_query_count ?? safeItems('Build Search Queries').length ?? 1;
const parsedJobs = safeItems('Parse Jobs').length;
const afterLocation = safeItems('location_filter').length;
const afterSemantic = safeItems('Semantic Dedupe').length;
const afterDedupe = safeItems('Remove Duplicates1').length;

const jobsLocationFiltered = Math.max(0, parsedJobs - afterLocation);
const jobsSemanticDeduped = Math.max(0, afterLocation - afterSemantic);
const jobsTitleCompanyDeduped = Math.max(0, afterSemantic - afterDedupe);

const analysisFailed = processed.filter(item =>
  item.json._was_new === true &&
  (item.json.analysis_status === 'fetch_failed' || item.json.analysis_status === 'extraction_failed')
).length;

const minScore = Number($('Get Search Config').first().json.config?.min_match_score ?? 40);

const scoreFiltered = processed.filter(item => {
  if (item.json._was_new !== true) return false;
  const score = Number(item.json.match_score ?? item.json.match?.score);
  return !Number.isNaN(score) && score < minScore;
}).length;

return [{
  json: {
    search_run_id: searchRun.id,
    results_found: resultsFound,
    search_query_count: searchQueryCount,
    parsed_jobs: parsedJobs,
    jobs_location_filtered: jobsLocationFiltered,
    jobs_semantic_deduped: jobsSemanticDeduped,
    jobs_deduped_pre_db: jobsTitleCompanyDeduped,
    new_jobs_found: newJobs,
    jobs_analyzed: newJobs,
    existing_jobs_seen: existingJobs,
    analysis_failed: analysisFailed,
    score_filtered: scoreFiltered,
    processed_jobs: processed.length
  }
}];

